'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const icon=n=>`<svg class="icon" aria-hidden="true"><use href="#i-${n}"/></svg>`;
const escapeHtml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
let stations=[],metadata={},map,stationLayer,portfolioLayer,selected=null,filter='all',role='client',tab='dashboard';
let demo={balance:0,portfolio:[],requests:[],tickets:[],activity:[]};
try{const saved=JSON.parse(localStorage.getItem('ecocharge-demo-v1'));if(saved&&Number.isFinite(saved.balance)&&Array.isArray(saved.portfolio)&&Array.isArray(saved.requests)&&Array.isArray(saved.tickets)&&Array.isArray(saved.activity))demo=saved}catch{}
function persist(){try{localStorage.setItem('ecocharge-demo-v1',JSON.stringify(demo))}catch{toast('Demo changes are available for this session only.')}renderNumbers()}
function renderNumbers(){$('#balance').textContent=money(demo.balance);$('#portfolio-count').textContent=demo.portfolio.length;$('#filter-portfolio-count').textContent=demo.portfolio.length}
function chart(){const p='M40 117 49 108 59 106 68 93 77 99 86 87 95 91 104 72 113 76 122 66 131 78 140 81 149 97 158 90 167 71 176 79 185 92 194 76 203 64 212 69 221 74 230 66 239 48 248 50 257 35 266 42 275 52 284 51 293 64 302 73 311 88 320 94 329 103 338 92 347 85 356 78 365 66 374 59 383 67 392 73 401 65 412 57';$('#chart-line').setAttribute('d',p);$('#chart-shadow').setAttribute('d',p);$('#chart-area').setAttribute('d',p+' L412 138 L40 138Z')}
function initMap(){if(!window.L){$('#map-error').hidden=false;$('#map-error').textContent='Map could not load. Station directory remains available.';return}map=L.map('map',{zoomControl:false,attributionControl:true,minZoom:2,maxZoom:16,zoomSnap:0.5,preferCanvas:true,scrollWheelZoom:false}).setView([38,-98],4);const tiles=L.tileLayer('https://services.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Dark_Gray_Base/MapServer/tile/{z}/{y}/{x}',{attribution:'Tiles &copy; Esri, HERE, Garmin | &copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:16}).addTo(map);let failures=0;tiles.on('tileerror',()=>{if(++failures>8){$('#map-error').hidden=false;$('#map-error').textContent='Map background is unavailable. Station markers and source links still work.'}});stationLayer=L.layerGroup().addTo(map);portfolioLayer=L.layerGroup().addTo(map);map.fitBounds([[24.8,-124.7],[49,-66.8]],{padding:[30,40]});renderMap()}
function filteredStations(){const state=$('#state-filter').value;const query=$('#station-search').value.trim().toLowerCase();return stations.filter(s=>(!state||s.state===state)&&(filter!=='portfolio'||demo.portfolio.includes(s.id))&&(!query||`${s.id} ${s.name} ${s.address} ${s.city} ${s.state}`.toLowerCase().includes(query)))}
function renderMap(){const visible=filteredStations();$('#map-count').textContent=`${visible.length.toLocaleString('en-US')} real locations`;if(!map)return;stationLayer.clearLayers();portfolioLayer.clearLayers();visible.forEach(s=>{const featured=demo.portfolio.includes(s.id)||s.id===selected?.id;if(featured){const marker=L.marker([s.lat,s.lng],{icon:L.divIcon({className:`station-marker ${s.id===selected?.id?'selected':''}`,html:icon('zap'),iconSize:[26,26],iconAnchor:[13,13]}),zIndexOffset:900});marker.addTo(portfolioLayer).on('click',()=>{selectStation(s.id);actions.station()});marker.bindTooltip(`<strong>EA-${s.id}</strong><br>${escapeHtml(s.city)}, ${s.state}<br>${s.ports} DC fast ports<small>${s.id===selected?.id?'Selected station':'Demo portfolio'}</small>`,{className:'station-tooltip',permanent:s.id===selected?.id,direction:s.lng<-100?'right':'left',offset:[14,-4]});}else{L.circleMarker([s.lat,s.lng],{radius:2.5,weight:.5,color:'#3db3e0',fillColor:'#2694b8',fillOpacity:.72}).addTo(stationLayer).bindTooltip(`${escapeHtml(s.name)} · ${s.ports} ports`,{className:'station-point-tip'}).on('click',()=>{selectStation(s.id);actions.station()})}})}
function selectStation(id,zoom=false){const s=stations.find(s=>s.id===Number(id));if(!s)return false;selected=s;$('#station-id').textContent=`AFDC ${s.id}`;$('#station-name').textContent=s.name;$('#station-address').textContent=`${s.address}, ${s.city}, ${s.state} ${s.zip}`;$('#station-power').textContent=s.maxKw?`${s.maxKw} kW max`:'Power not listed';$('#station-ports').textContent=`${s.ports} DC fast ports`;$('#station-connectors').textContent=s.connectors.map(c=>({J1772COMBO:'CCS',CHADEMO:'CHAdeMO',TESLA:'NACS',J1772:'J1772'}[c]||c)).join(' · ');$('#confirmed-date').textContent=`Confirmed: ${s.confirmed}`;$('#maps-link').href=`https://www.google.com/maps/search/?api=1&query=${s.lat},${s.lng}`;$('#source-link').href=s.source;if(zoom&&map)map.setView([s.lat,s.lng],8,{animate:!matchMedia('(prefers-reduced-motion: reduce)').matches});renderMap();return true}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
async function init(){chart();renderNumbers();try{const response=await fetch('stations.json');if(!response.ok)throw Error('Directory unavailable');metadata=await response.json();stations=metadata.stations;$('#station-total').textContent=stations.length.toLocaleString('en-US');$('#available-count').textContent=stations.length.toLocaleString('en-US');$('#feed-count').textContent=`${stations.length.toLocaleString('en-US')} stations`;$('#snapshot-date').textContent=`Snapshot ${metadata.fetchedAt.slice(0,10)}`;[...new Set(stations.map(s=>s.state))].sort().forEach(s=>$('#state-filter').add(new Option(s,s)));selected=stations.find(s=>s.id===371815)||stations[0];initMap();selectStation(selected.id);setRole(window.PORTAL_ROLE||'client')}catch(e){$('#map-error').hidden=false;$('#map-error').textContent='Station directory could not be loaded. Reload to try again.';console.error(e)}}
let requestCounter=0;
const clients=[{id:'CL-1001',name:'John Doe',email:'john.doe@example.com',initials:'JD',state:'Active'},{id:'CL-1002',name:'Emily Carter',email:'emily.carter@example.com',initials:'EC',state:'Review'},{id:'CL-1003',name:'Michael Reed',email:'michael.reed@example.com',initials:'MR',state:'Active'}];
let adminTab='overview';
function activity(text){demo.activity.unshift({text,date:new Date().toISOString()});demo.activity=demo.activity.slice(0,60)}
function pendingWithdrawals(){return demo.requests.filter(r=>r.type==='withdraw'&&r.status==='Pending').reduce((n,r)=>n+r.amount,0)}
function openModal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function setRole(next){role=next==='admin'?'admin':'client';$('#client-view').hidden=role!=='client';$('#admin-view').hidden=role!=='admin';$$('[data-role]').forEach(b=>b.classList.toggle('active',b.dataset.role===role));$('#profile-name').textContent=role==='admin'?'Alex Brown':'John Doe';$('.avatar').textContent=role==='admin'?'AB':'JD';$('#profile-role').textContent=role==='admin'?'STAFF · DEMO':'EN · DEMO';const url=new URL(location);url.searchParams.set('view',role);history.replaceState({},'',url);renderNav();if(role==='admin')renderAdmin();else{renderClientTab();setTimeout(()=>map?.invalidateSize(),50)}window.scrollTo({top:0,behavior:'instant'})}
function renderNav(){const navs=role==='admin'?[['overview','grid','Overview'],['clients','users','Clients'],['stations','map','Station Directory'],['requests','assets','Requests']]:[['dashboard','grid','Dashboard'],['map','map','Interactive Map'],['assets','assets','My Assets'],['documents','download','Download Center']];$('.main-nav').innerHTML=navs.map(([id,i,label])=>`<button class="nav-item ${(role==='admin'?adminTab:tab)===id?'active':''}" data-tab="${id}">${icon(i)}<span>${label}</span></button>`).join('')}
function renderClientTab(){const root=$('#client-view');root.className=`view-${tab}`;$('.metrics-grid').hidden=tab!=='dashboard';$('#map-section').hidden=!['dashboard','map'].includes(tab);$('.bottom-grid').hidden=!['dashboard','documents'].includes(tab);$('#asset-list-section').hidden=tab!=='assets';if(tab==='assets')renderPortfolio();renderNav();setTimeout(()=>map?.invalidateSize(),30)}
function renderPortfolio(){$('#asset-list').innerHTML=demo.portfolio.length?demo.portfolio.map(id=>stations.find(s=>s.id===id)).filter(Boolean).map(s=>`<div class="portfolio-row"><span class="large-orb">${icon('zap')}</span><div><strong>${escapeHtml(s.name)}</strong><small>${escapeHtml(s.address)} · ${s.city}, ${s.state}</small><p><span class="pill">DEMO SELECTION</span> <span class="muted">${s.ports} DC fast ports · ${s.maxKw||'—'} kW max</span></p></div><button class="button secondary" data-open-station="${s.id}">${icon('map')}View on map</button></div>`).join(''):'<div class="empty-state">No demo stations assigned. Add a station from the Staff console.</div>'}
function renderAdmin(){const pending=demo.requests.filter(r=>r.status==='Pending');$('#admin-view').innerHTML=`<section class="panel admin-hero"><div><h1>Staff Operations Console</h1><p>Manage demo clients, requests and station assignments.</p></div><span class="staff-tag">${icon('shield')} LOCAL DEMO</span></section><section class="admin-kpis"><div class="panel admin-kpi">${icon('users')}<span>Demo clients</span><strong>3</strong></div><div class="panel admin-kpi">${icon('assets')}<span>Pending requests</span><strong>${pending.length}</strong></div><div class="panel admin-kpi">${icon('zap')}<span>Real charging locations</span><strong>${stations.length.toLocaleString('en-US')}</strong></div><div class="panel admin-kpi">${icon('chat')}<span>Open support tickets</span><strong>${demo.tickets.filter(t=>t.status==='Open').length}</strong></div></section><div class="admin-layout"><div>${['overview','clients'].includes(adminTab)?clientTable():''}${['overview','requests'].includes(adminTab)?requestTable():''}${adminTab==='stations'?stationDirectory():''}${['overview','requests'].includes(adminTab)?supportTable():''}</div><aside>${assignmentPanel()}${activityPanel()}</aside></div>`;$('#notification-count').textContent=String(pending.length+demo.tickets.filter(t=>t.status==='Open').length||0);renderNav()}
function clientTable(){return `<section class="panel admin-section"><div class="section-heading"><h2>${icon('users')} CLIENTS</h2><span>Fictional demo profiles</span></div><div class="table-scroll"><table><thead><tr><th>Client</th><th>Status</th><th>Balance</th><th>Actions</th></tr></thead><tbody>${clients.map((c,i)=>`<tr><td><strong>${c.name}</strong><small>${c.id}</small></td><td><span class="pill ${c.state==='Review'?'pending':''}">${c.state}</span></td><td>${i===0?money(demo.balance):'—'}</td><td><button class="table-button" data-client="${c.id}">Open profile</button></td></tr>`).join('')}</tbody></table></div></section>`}
function requestTable(){return `<section class="panel admin-section"><div class="section-heading"><h2>${icon('assets')} TRANSACTION REQUESTS</h2><span>Simulation only</span></div>${demo.requests.length?`<div class="table-scroll"><table><thead><tr><th>Client / request</th><th>Amount</th><th>Status</th><th>Review</th></tr></thead><tbody>${demo.requests.slice().reverse().map(r=>`<tr><td><strong>John Doe</strong><small>${r.type==='topup'?'Top up':'Withdrawal'} · ${r.id}</small></td><td>${money(r.amount)}</td><td><span class="pill ${r.status.toLowerCase()}">${r.status}</span></td><td>${r.status==='Pending'?`<div class="request-actions"><button class="table-button approve" data-review="${r.id}" data-decision="approve">Approve</button><button class="table-button reject" data-review="${r.id}" data-decision="reject">Reject</button></div>`:escapeHtml(r.reason||'Reviewed')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No requests yet.<br>Create a top-up or withdrawal in the Client portal.</div>'}</section>`}
function stationDirectory(){return `<section class="panel admin-section"><div class="section-heading"><h2>${icon('map')} REAL STATION DIRECTORY</h2><span>Electrify America · AFDC</span></div><input class="admin-search" id="admin-station-search" placeholder="Search city, state, station name or AFDC ID…" aria-label="Search station directory"><div id="admin-station-results">${directoryRows(stations.slice(0,18))}</div><p class="muted" style="font-size:12px">Public directory records. Neither ownership nor a partnership is implied.</p></section>`}
function directoryRows(rows){return rows.length?`<div class="table-scroll"><table><thead><tr><th>Station</th><th>DC ports</th><th>Action</th></tr></thead><tbody>${rows.map(s=>`<tr><td><strong>${escapeHtml(s.city)}, ${s.state}</strong><small>${escapeHtml(s.name)} · ${s.id}</small></td><td>${s.ports}</td><td><button class="table-button" data-assign="${s.id}" ${demo.portfolio.includes(s.id)?'disabled':''}>${demo.portfolio.includes(s.id)?'Assigned':'Assign to John'}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No matching stations.</div>'}
function assignmentPanel(){return `<section class="panel admin-section"><div class="section-heading"><h2>${icon('zap')} DEMO PORTFOLIO</h2><span>John Doe</span></div><p class="muted" style="font-size:12px">Assignments are demo selections, not ownership records.</p>${demo.portfolio.map(id=>stations.find(s=>s.id===id)).filter(Boolean).map(s=>`<div class="activity-row"><strong>${escapeHtml(s.city)}, ${s.state}</strong><button class="table-button" style="float:right" data-unassign="${s.id}">Remove</button><small>AFDC ${s.id} · ${s.ports} ports</small></div>`).join('')||'<div class="empty-state">No stations assigned.</div>'}<div class="assign-row"><select id="assign-station" aria-label="Station to assign">${stations.filter(s=>!demo.portfolio.includes(s.id)).sort((a,b)=>a.state.localeCompare(b.state)||a.city.localeCompare(b.city)).map(s=>`<option value="${s.id}">${escapeHtml(s.city)}, ${s.state} · ${escapeHtml(s.name)}</option>`).join('')}</select><button class="table-button" data-action="assign-station">Add</button></div></section>`}
function activityPanel(){return `<section class="panel admin-section"><h2>${icon('calendar')} ACTIVITY LOG</h2>${demo.activity.length?demo.activity.slice(0,8).map(a=>`<div class="activity-row">${escapeHtml(a.text)}<small>${new Date(a.date).toLocaleString('en-US')}</small></div>`).join(''):'<div class="empty-state">Your demo actions will appear here.</div>'}</section><div class="notice"><span>ⓘ</span><p>Separate demo accounts.<br>Changes sync between tabs in this browser.</p></div>`}
function supportTable(){return `<section class="panel admin-section"><div class="section-heading"><h2>${icon('chat')} SUPPORT INBOX</h2><span>${demo.tickets.length} tickets</span></div>${demo.tickets.length?demo.tickets.slice().reverse().map(t=>`<div class="ticket-row"><strong>John Doe · ${escapeHtml(t.subject)}</strong><span class="pill ${t.status==='Open'?'pending':''}" style="float:right">${t.status}</span><p>${escapeHtml(t.message)}</p>${t.reply?`<p><strong>Reply:</strong> ${escapeHtml(t.reply)}</p>`:''}<small class="muted">${t.id}</small>${t.status==='Open'?`<button class="table-button" data-reply="${t.id}">Reply & resolve</button>`:''}</div>`).join(''):'<div class="empty-state">No support messages.<br>Use the chat button in the Client portal.</div>'}</section>`}
function paymentModal(type){const available=Math.max(0,demo.balance-pendingWithdrawals());openModal(`<h2>${type==='topup'?'Top Up Account':'Withdraw Profit'}</h2><p>${type==='topup'?'Create a demo deposit request. A staff member can approve it in the Staff console.':`Available in the demo: <strong>${money(available)}</strong>. Pending withdrawals are reserved.`}</p><div class="modal-note">SIMULATION · No payment is collected and no money is transferred.</div><form id="payment-form" data-type="${type}"><label for="payment-amount">Amount (USD)</label><input id="payment-amount" name="amount" type="number" inputmode="decimal" min="1" max="${type==='topup'?100000:available}" step="0.01" value="${type==='topup'?250:Math.min(100,available).toFixed(2)}" required><div class="quick-amounts">${[50,100,250].map(n=>`<button type="button" data-amount="${n}">$${n}</button>`).join('')}</div><div class="form-error" id="payment-error" role="alert"></div><button class="button primary" type="submit">Submit demo request ${icon('arrow')}</button></form>`)}
function supportModal(kind='chat'){const existing=demo.tickets.slice().reverse();openModal(`<h2>${kind==='call'?'Request a call':kind==='message'?'Message your manager':'Support conversation'}</h2><p>Messages appear in the Staff console. This is a local demo inbox.</p>${kind==='chat'&&existing.length?`<ul class="modal-list">${existing.slice(0,4).map(t=>`<li><strong>You: ${escapeHtml(t.message)}</strong><small>${t.reply?`Alex: ${escapeHtml(t.reply)}`:'Awaiting staff response'}</small></li>`).join('')}</ul>`:''}<form id="support-form" data-kind="${kind}"><label for="support-message">${kind==='call'?'Preferred time and topic':'Your message'}</label><textarea id="support-message" maxlength="1500" required placeholder="${kind==='call'?'Tomorrow at 10:00 ET, portfolio overview…':'How can we help?'}"></textarea><div class="form-error" role="alert" id="support-error"></div><button class="button primary" type="submit">${kind==='call'?'Request demo callback':'Send message'} ${icon('arrow')}</button></form>`)}
function reviewRequest(id,decision){const r=demo.requests.find(r=>r.id===id);if(!r||r.status!=='Pending')return toast('This request has already been reviewed.');openModal(`<h2>${decision==='approve'?'Approve':'Reject'} demo ${r.type==='topup'?'top-up':'withdrawal'}</h2><p>John Doe · <strong>${money(r.amount)}</strong><br>Request ${escapeHtml(r.id)}</p><div class="modal-note">Only the simulated balance will change. No real transaction will occur.</div><form id="review-form" data-request="${r.id}" data-decision="${decision}">${decision==='reject'?'<label for="review-reason">Reason</label><textarea id="review-reason" maxlength="250" required placeholder="Explain why the demo request was declined"></textarea>':''}<div id="review-error" class="form-error" role="alert"></div><button class="button primary" type="submit">Confirm ${decision==='approve'?'approval':'rejection'}</button></form>`)}
function assignStation(id){id=Number(id);if(!stations.some(s=>s.id===id)||demo.portfolio.includes(id))return;demo.portfolio.push(id);activity(`Assigned AFDC ${id} to John Doe's demo portfolio`);persist();renderMap();renderAdmin();toast('Station added to the demo portfolio.')}
function showClient(id){const c=clients.find(c=>c.id===id);if(!c)return;openModal(`<h2>${c.name}</h2><p>${c.id} · Fictional client profile</p><ul class="modal-list"><li><strong>Email</strong><small>${c.email}</small></li><li><strong>Account status</strong><small>${c.state}</small></li><li><strong>Demo balance</strong><small>${c.id==='CL-1001'?money(demo.balance):'No demo transactions'}</small></li><li><strong>Assigned stations</strong><small>${c.id==='CL-1001'?demo.portfolio.length:0}</small></li></ul>${c.id==='CL-1001'?'<button class="button primary" data-action="view-client">Open client portal</button>':'<div class="modal-note">This profile is a directory sample. Interactive transactions use John Doe.</div>'}`)}
function notifyModal(){openModal(`<h2>Notifications</h2><ul class="modal-list"><li><strong>Real US station directory connected</strong><small>${stations.length.toLocaleString('en-US')} DC fast charging locations · AFDC snapshot ${metadata.fetchedAt?.slice(0,10)}</small></li><li><strong>Investor workspace ready</strong><small>Your balances and portfolio are demo data.</small></li>${demo.requests.slice(-4).reverse().map(r=>`<li><strong>${r.type==='topup'?'Top-up':'Withdrawal'} ${money(r.amount)} · ${r.status}</strong><small>${escapeHtml(r.reason||r.id)}</small></li>`).join('')}${demo.tickets.filter(t=>t.reply).map(t=>`<li><strong>Support replied</strong><small>${escapeHtml(t.reply)}</small></li>`).join('')}</ul>`)}
