const actions={topup:()=>paymentModal('topup'),withdraw:()=>paymentModal('withdraw'),notifications:notifyModal,profile:()=>showClient('CL-1001'),contract:()=>downloadPdf('contract'),factsheet:()=>downloadPdf('factsheet'),chat:()=>supportModal('chat'),call:()=>supportModal('call'),message:()=>supportModal('message'),'view-client':()=>{$('#modal').close();setRole('client')},'assign-station':()=>assignStation($('#assign-station').value),'zoom-in':()=>map?.zoomIn(),'zoom-out':()=>map?.zoomOut(),'fit-map':()=>{const rows=filteredStations();if(rows.length)map?.fitBounds(rows.map(s=>[s.lat,s.lng]),{padding:[45,65],maxZoom:8})},period:()=>openModal('<h2>Performance period</h2><p>Choose a period for the simulated chart.</p><div class="quick-amounts"><button data-period="7">7 days</button><button data-period="30">30 days</button><button data-period="90">90 days</button></div>'),feed:()=>{const rows=stations.slice().sort((a,b)=>b.confirmed.localeCompare(a.confirmed)).slice(0,6);openModal(`<h2>US Charging Network Feed</h2><p>Directory snapshot from AFDC. These are source confirmation dates, not live charging events.</p>${rows.map(s=>`<div class="feed-entry"><strong>${escapeHtml(s.name)}</strong><small>${s.ports} DC fast ports · Confirmed ${s.confirmed}</small><br><button class="inline-action" data-feed-station="${s.id}">View station</button></div>`).join('')}`)},briefing:()=>openModal('<h2>Infrastructure briefing</h2><p>Demo agenda: station locations, connector types, source confirmation dates and the difference between directory data and live telemetry.</p><div class="modal-note">No live event is scheduled in this prototype.</div><button class="button primary" data-action="chat">Ask a question in demo support</button>'),reset:()=>openModal('<h2>Reset this demo?</h2><p>This clears only the demo requests, support messages and station assignments saved in this browser.</p><button class="button primary" data-action="confirm-reset">Reset demo data</button>'),'confirm-reset':()=>{demo={balance:1280.45,portfolio:[371815,127227],requests:[],tickets:[],activity:[]};persist();$('#modal').close();renderMap();renderPortfolio();if(role==='admin')renderAdmin();toast('Demo restored to its initial state.')}};
function initInteractions(){document.addEventListener('click',e=>{const b=e.target.closest('button,[data-action][role="button"]');if(!b)return;if(b.dataset.role)setRole(b.dataset.role);else if(b.dataset.tab){if(role==='admin'){adminTab=b.dataset.tab;renderAdmin()}else{tab=b.dataset.tab;renderClientTab()}}else if(b.dataset.action&&actions[b.dataset.action])actions[b.dataset.action]();else if(b.dataset.filter){filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderMap()}else if(b.dataset.selectStation){selectStation(b.dataset.selectStation,true);$('#search-results').hidden=true;$('#station-search').value='';$('#clear-search').hidden=true;renderMap()}else if(b.dataset.amount){$('#payment-amount').value=b.dataset.amount;$('#payment-amount').focus()}else if(b.dataset.openStation){tab='map';renderClientTab();selectStation(b.dataset.openStation,true)}else if(b.dataset.feedStation){$('#modal').close();setRole('client');tab='map';renderClientTab();selectStation(b.dataset.feedStation,true)}else if(b.dataset.client)showClient(b.dataset.client);else if(b.dataset.review)reviewRequest(b.dataset.review,b.dataset.decision);else if(b.dataset.assign)assignStation(b.dataset.assign);else if(b.dataset.unassign){const id=Number(b.dataset.unassign);demo.portfolio=demo.portfolio.filter(v=>v!==id);activity(`Removed AFDC ${id} from John Doe's demo portfolio`);persist();renderMap();renderAdmin();toast('Station removed from demo portfolio.')}else if(b.dataset.reply){const t=demo.tickets.find(t=>t.id===b.dataset.reply);if(t)openModal(`<h2>Reply to John Doe</h2><p>${escapeHtml(t.message)}</p><form id="reply-form" data-ticket="${t.id}"><label for="reply-text">Staff reply</label><textarea id="reply-text" required maxlength="1500"></textarea><div class="form-error" id="reply-error" role="alert"></div><button class="button primary" type="submit">Send reply & resolve</button></form>`)}else if(b.dataset.period){const days=Number(b.dataset.period);$('.period-button').innerHTML=`Last ${days} days <span>⌄</span>`;$('#yield-percent').innerHTML=days===7?'+0.34<span>%</span>':days===90?'+1.27<span>%</span>':'+0.82<span>%</span>';const labels=days===7?['Sep 09','Sep 11','Sep 13','Sep 15','Today']:days===90?['Jun 18','Jul 10','Aug 02','Aug 24','Today']:['Aug 17','Aug 24','Aug 31','Sep 07','Today'];$('.chart-dates').innerHTML=labels.map(d=>`<span>${d}</span>`).join('');$('#yield-chart g[transform] text').textContent=days===7?'+0.34%':days===90?'+1.27%':'+0.82%';$('#chart-line').style.opacity=days===7?'.8':'1';$('#modal').close();toast(`${days}-day simulated chart selected.`)}});
$('#close-modal').addEventListener('click',()=>$('#modal').close());$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
$('#state-filter').addEventListener('change',()=>{renderMap();actions['fit-map']()});$('#station-search').addEventListener('input',()=>{const query=$('#station-search').value.trim();$('#clear-search').hidden=!query;const matches=filteredStations();renderMap();$('#search-results').hidden=!query;if(query)$('#search-results').innerHTML=matches.length?matches.slice(0,8).map(s=>`<button class="search-result" data-select-station="${s.id}"><strong>${escapeHtml(s.city)}, ${s.state} · ${s.id}</strong><small>${escapeHtml(s.name)}</small></button>`).join(''):'<div class="no-results">No stations found. Try a city, state or AFDC ID.</div>'});$('#station-search').addEventListener('keydown',e=>{if(e.key==='Escape')$('#search-results').hidden=true;if(e.key==='Enter')$('#search-results button')?.click();if(e.key==='ArrowDown'){e.preventDefault();$('#search-results button')?.focus()}});$('#clear-search').addEventListener('click',()=>{$('#station-search').value='';$('#station-search').dispatchEvent(new Event('input'));$('#station-search').focus()});document.addEventListener('click',e=>{if(!e.target.closest('.map-search'))$('#search-results').hidden=true});
document.addEventListener('input',e=>{if(e.target.id==='admin-station-search'){const q=e.target.value.toLowerCase().trim();const rows=stations.filter(s=>`${s.name} ${s.city} ${s.state} ${s.id}`.toLowerCase().includes(q));$('#admin-station-results').innerHTML=directoryRows(rows.slice(0,30))}});
document.addEventListener('submit',e=>{if(!e.target.matches('#payment-form,#support-form,#review-form,#reply-form'))return;e.preventDefault();const form=e.target;if(form.id==='payment-form'){const amount=Number($('#payment-amount').value),type=form.dataset.type,available=demo.balance-pendingWithdrawals();if(!Number.isFinite(amount)||amount<1||amount>100000||Math.abs(amount*100-Math.round(amount*100))>0.00001||(type==='withdraw'&&amount>available)){$('#payment-error').textContent='Enter a valid amount within the available demo balance (two decimals maximum).';return}const id=`REQ-${Date.now().toString(36).toUpperCase()}-${++requestCounter}`;demo.requests.push({id,type,amount:Math.round(amount*100)/100,status:'Pending',date:new Date().toISOString()});activity(`John Doe requested a demo ${type==='topup'?'top-up':'withdrawal'} of ${money(amount)}`);persist();openModal(`<div class="success-icon">✓</div><h2>Demo request submitted</h2><p>${money(amount)} · ${type==='topup'?'Top up':'Withdrawal'}<br>Status: Pending staff review.</p><div class="modal-note">Switch to Staff console to approve or reject this request.</div><button class="button primary" data-action="open-staff">Open Staff console ${icon('arrow')}</button>`);actions['open-staff']=()=>{$('#modal').close();adminTab='requests';setRole('admin')}}
else if(form.id==='support-form'){const message=$('#support-message').value.trim();if(message.length<3){$('#support-error').textContent='Please enter at least 3 characters.';return}demo.tickets.push({id:`TKT-${Date.now().toString(36).toUpperCase()}`,subject:form.dataset.kind==='call'?'Callback request':'Support message',message,status:'Open',date:new Date().toISOString(),reply:''});activity('John Doe opened a demo support ticket');persist();$('#modal').close();toast('Message sent to the demo Staff console.')}
else if(form.id==='review-form'){const r=demo.requests.find(r=>r.id===form.dataset.request);if(!r||r.status!=='Pending'){$('#modal').close();return toast('Request already reviewed.')}if(form.dataset.decision==='approve'){if(r.type==='withdraw'&&r.amount>demo.balance){$('#review-error').textContent='The demo account has insufficient funds.';return}demo.balance=Math.round((demo.balance+(r.type==='topup'?r.amount:-r.amount))*100)/100;r.status='Approved'}else{const reason=$('#review-reason').value.trim();if(reason.length<3){$('#review-error').textContent='Enter a reason of at least 3 characters.';return}r.status='Rejected';r.reason=reason}r.reviewedAt=new Date().toISOString();activity(`${r.status} ${r.id} (${money(r.amount)})`);persist();$('#modal').close();renderAdmin();toast(`Demo request ${r.status.toLowerCase()}.`)}
else if(form.id==='reply-form'){const t=demo.tickets.find(t=>t.id===form.dataset.ticket);const reply=$('#reply-text').value.trim();if(reply.length<3){$('#reply-error').textContent='Enter a reply of at least 3 characters.';return}if(t){t.reply=reply;t.status='Resolved';activity(`Resolved support ticket ${t.id}`);persist()}$('#modal').close();renderAdmin();toast('Reply saved. It is visible in the Client portal.')}
});setRole(window.PORTAL_ROLE||(new URL(location).searchParams.get('view')==='admin'?'admin':'client'));registerTools()}
function registerTools(){if(!document.modelContext?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:'list_charging_stations',title:'Find real US charging stations',description:'Read imported public AFDC station data. No live occupancy or ownership information.',inputSchema:{type:'object',properties:{query:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||input.query!==undefined&&typeof input.query!=='string')throw Error('query must be a string');const q=(input.query||'').toLowerCase();return stations.filter(s=>`${s.city} ${s.state} ${s.name} ${s.id}`.toLowerCase().includes(q)).slice(0,20).map(s=>({id:s.id,name:s.name,city:s.city,state:s.state,ports:s.ports,source:s.source}))}},{name:'select_charging_station',title:'Select a station on the map',description:'Change the selected station in the visible client portal. Does not create an investment or assign ownership.',inputSchema:{type:'object',properties:{station_id:{type:'integer'}},required:['station_id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||!Number.isInteger(input.station_id)||!stations.some(s=>s.id===input.station_id))throw Error('Unknown station ID');setRole('client');tab='map';renderClientTab();selectStation(input.station_id,true);return {selected_id:selected.id,city:selected.city}}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
actions.portfolio=()=>{tab='assets';renderClientTab()};
actions.yield=()=>openModal(`<h2>Yield breakdown</h2><p>Simulated performance for the last 30 days.</p><ul class="modal-list"><li><strong>Gross demo accrual</strong><small>$384.60</small></li><li><strong>Demo operating allocation</strong><small>-$28.42</small></li><li><strong>Net simulated yield</strong><small>$356.18</small></li></ul><div class="modal-note">Illustrative figures only. They are not connected to the listed stations' operating or financial data.</div>`);
actions.history=()=>openModal(`<h2>Account activity</h2><p>Demo balance: ${money(demo.balance)} · Reserved: ${money(pendingWithdrawals())}</p>${demo.requests.length?`<ul class="modal-list">${demo.requests.slice().reverse().map(r=>`<li><strong>${r.type==='topup'?'Top up':'Withdrawal'} · ${money(r.amount)}</strong><small>${r.status} · ${escapeHtml(r.reason||r.id)}</small></li>`).join('')}</ul>`:'<div class="empty-state">No transactions yet.</div>'}<button class="button primary" data-action="topup">Create a demo top-up</button>`);
actions.station=()=>{if(!selected)return;const s=selected;openModal(`<h2>${escapeHtml(s.name)}</h2><p>${escapeHtml(s.address)}, ${escapeHtml(s.city)}, ${s.state} ${s.zip}</p><ul class="modal-list"><li><strong>Operator network</strong><small>${escapeHtml(s.network)}</small></li><li><strong>DC fast ports / maximum listed power</strong><small>${s.ports} ports / ${s.maxKw||'Not listed'} kW</small></li><li><strong>Access hours</strong><small>${escapeHtml(s.access||'Not listed')}</small></li><li><strong>Coordinates</strong><small>${s.lat}, ${s.lng}</small></li><li><strong>Public directory confirmation</strong><small>${s.confirmed} · Not live occupancy</small></li></ul><a class="button primary" href="${s.source}" target="_blank" rel="noopener">Open AFDC source ${icon('out')}</a><button class="button secondary" data-action="factsheet">Download fact sheet</button>`)};
actions.manager=()=>openModal(`<h2>Alexander Brown</h2><p>Demo account manager · ALT-INFRA workspace</p><ul class="modal-list"><li><strong>Client</strong><small>John Doe · CL-1001</small></li><li><strong>Support requests</strong><small>${demo.tickets.filter(t=>t.status==='Open').length} open / ${demo.tickets.filter(t=>t.status==='Resolved').length} resolved</small></li></ul><button class="button primary" data-action="chat">Open support conversation</button><button class="button secondary" data-action="call">Request a callback</button>`);
actions.profile=()=>role==='admin'?actions.manager():showClient('CL-1001');
function enhanceClickableSurfaces(){for(const [selector,action,label] of [['.balance','history','View account activity'],['.metric-card:first-of-type','portfolio','View demo portfolio'],['.metrics-grid .metric-card:nth-last-child(2)','portfolio','View demo portfolio'],['.metrics-grid .metric-card:last-child','yield','View simulated yield breakdown'],['.yield-summary','yield','View performance details'],['.station-photo','station','View selected station details'],['.manager-row','manager','View account manager']]){const node=$(selector);if(!node)continue;node.dataset.action=action;node.setAttribute('role','button');node.setAttribute('tabindex','0');node.setAttribute('aria-label',label)}document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-action][role="button"]')){e.preventDefault();actions[e.target.dataset.action]?.()}})}
enhanceClickableSurfaces();
window.addEventListener('DOMContentLoaded',()=>{initInteractions();init()});
